def whois_lookup(target, **_extra):
    import json, os, datetime, time, uuid, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0003000" if __import__("os").path.isdir("./environment_mix/0003000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    # ---- helpers ----
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _sha256_text(s):
        if s is None:
            return None
        if not isinstance(s, str):
            s = str(s)
        return hashlib.sha256(s.encode("utf-8", errors="replace")).hexdigest()

    def _truncate_text(text, max_bytes=10485760):
        if text is None:
            return None, 0, False
        if not isinstance(text, str):
            text = str(text)
        b = text.encode("utf-8", errors="replace")
        if len(b) <= max_bytes:
            return text, len(b), False
        b2 = b[:max_bytes]
        t2 = b2.decode("utf-8", errors="ignore")
        final = t2 + "\n[TRUNCATED: output exceeded 10MB]"
        return final, len(final.encode("utf-8", errors="replace")), True

    def _append_usage(events, client_id, event_type, investigation_id=None, tool_run_id=None, tool_name=None, status=None):
        ts = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        row = {
            "id": _gen_id("osint_ue"),
            "client_id": client_id,
            "event_type": event_type,
            "investigation_id": investigation_id,
            "tool_run_id": tool_run_id,
            "tool_name": tool_name,
            "occurred_at": ts.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "meta": {"endpoint": "whois_lookup", "status": status} if status else {"endpoint": "whois_lookup"},
            "created_at": ts.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "updated_at": ts.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        }
        events.append(row)
        return row

    def _rpm_count(events, client_id, since_dt):
        c = 0
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_id:
                continue
            odt = _parse_dt(e.get("occurred_at"))
            if odt and odt >= since_dt:
                c += 1
        return c

    def _count_type(events, client_id, event_type, since_dt):
        c = 0
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_id or e.get("event_type") != event_type:
                continue
            odt = _parse_dt(e.get("occurred_at"))
            if odt and odt >= since_dt:
                c += 1
        return c

    def _choose_active_client_under_limits(api_clients, usage_events):
        # Ambient auth: choose ANY active client that can currently serve a tool run.
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(hours=24)

        candidates = []
        for c in api_clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            rpm_limit = c.get("requests_per_minute_limit")
            tool_limit = c.get("daily_tool_run_limit")
            if not isinstance(rpm_limit, int) or rpm_limit < 1:
                continue
            if not isinstance(tool_limit, int) or tool_limit < 0:
                continue
            cid = c.get("id")
            if not isinstance(cid, str) or not cid:
                continue

            rpm = _rpm_count(usage_events, cid, minute_ago)
            tool_created_24h = _count_type(usage_events, cid, "tool_run_created", day_ago)
            if rpm >= rpm_limit:
                continue
            if tool_created_24h >= tool_limit:
                continue
            candidates.append((rpm, tool_created_24h, c))

        if not candidates:
            # Determine best error code (rate vs quota) by checking if any active exists
            actives = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active"]
            if not actives:
                return None, _err("UNAUTHORIZED", "No active API client is available to serve this request.")
            # If any active, figure whether all are blocked by RPM or quota
            any_under_rpm = False
            any_under_quota = False
            for c in actives:
                cid = c.get("id")
                rpm_limit = c.get("requests_per_minute_limit")
                tool_limit = c.get("daily_tool_run_limit")
                if not isinstance(cid, str) or not isinstance(rpm_limit, int) or not isinstance(tool_limit, int):
                    continue
                rpm = _rpm_count(usage_events, cid, minute_ago)
                tool_created_24h = _count_type(usage_events, cid, "tool_run_created", day_ago)
                if rpm < rpm_limit:
                    any_under_rpm = True
                if tool_created_24h < tool_limit:
                    any_under_quota = True
            if not any_under_rpm:
                return None, _err("RATE_LIMIT", "Requests per minute limit exceeded.")
            return None, _err("QUOTA_EXCEEDED", "Daily tool run quota exceeded.")
        candidates.sort(key=lambda x: (x[0], x[1]))
        return candidates[0][2], None

    # ---- validate ----
    if not isinstance(target, str) or not target.strip():
        # cannot attribute to a client reliably; do not log a client_id event
        return _err("VALIDATION_ERROR", "target must be a non-empty string")
    if len(target) > 2048:
        return _err("VALIDATION_ERROR", "target length must be between 1 and 2048")

    api_clients = _load("api_clients.json")
    tool_runs = _load("tool_runs.json")
    artifacts = _load("tool_run_artifacts.json")
    usage_events = _load("usage_events.json")

    client, auth_err = _choose_active_client_under_limits(api_clients, usage_events)
    if auth_err:
        # best-effort: log an unattributed attempt is not possible with schema (client_id non-null)
        return auth_err

    client_id = client["id"]

    # ---- create tool_run (queued -> running -> succeeded) and artifacts ----
    started = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    tool_run_id = _gen_id("osint_run")
    run_row = {
        "id": tool_run_id,
        "client_id": client_id,
        "investigation_id": None,
        "tool_name": "whois_lookup",
        "input_target": target,
        "input_domain": None,
        "status": "running",
        "exit_code": 0,
        "error_message": None,
        "duration_ms": None,
        "started_at": started.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        "finished_at": None,
        "created_at": started.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        "updated_at": started.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    }
    tool_runs.append(run_row)
    _append_usage(usage_events, client_id, "tool_run_created", tool_run_id=tool_run_id, tool_name="whois_lookup", status="running")

    # Simulated execution (offline): produce a plausible stdout and minimal parsed summary.
    stdout = f"WHOIS lookup simulated (offline)\nTarget: {target}\nTimestamp: {now_iso}\n"
    summary = {"target": target, "note": "Offline simulation; no external WHOIS query performed."}

    out_text, out_bytes, redacted = _truncate_text(stdout)
    art_id = _gen_id("osint_art")
    artifacts.append({
        "id": art_id,
        "tool_run_id": tool_run_id,
        "artifact_type": "stdout",
        "content_text": out_text,
        "content_json": None,
        "content_sha256": _sha256_text(out_text),
        "bytes": out_bytes,
        "redacted": bool(redacted),
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    # parsed summary artifact
    sum_json = summary
    sum_bytes = len(json.dumps(sum_json, ensure_ascii=False).encode("utf-8"))
    if sum_bytes > 10485760:
        # truncate by replacing with note
        sum_json = {"target": target, "note": "TRUNCATED: parsed_summary exceeded 10MB"}
        sum_bytes = len(json.dumps(sum_json, ensure_ascii=False).encode("utf-8"))
        redacted = True
    artifacts.append({
        "id": _gen_id("osint_art"),
        "tool_run_id": tool_run_id,
        "artifact_type": "whois_record",
        "content_text": None,
        "content_json": sum_json,
        "content_sha256": _sha256_text(json.dumps(sum_json, ensure_ascii=False)),
        "bytes": sum_bytes,
        "redacted": bool(redacted),
        "created_at": now_iso,
        "updated_at": now_iso,
    })

    finished = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    dur_ms = int(max(0, (finished - started).total_seconds() * 1000))
    run_row["status"] = "succeeded"
    run_row["finished_at"] = finished.replace(microsecond=0).isoformat().replace("+00:00", "Z")
    run_row["duration_ms"] = dur_ms
    run_row["updated_at"] = run_row["finished_at"]
    _append_usage(usage_events, client_id, "tool_run_completed", tool_run_id=tool_run_id, tool_name="whois_lookup", status="succeeded")

    # update client last_seen_at
    client["last_seen_at"] = now_iso
    client["updated_at"] = now_iso

    _save("tool_runs.json", tool_runs)
    _save("tool_run_artifacts.json", artifacts)
    _save("usage_events.json", usage_events)
    _save("api_clients.json", api_clients)

    return {
        "tool_run": run_row,
        "artifacts": [
            {"artifact_type": "stdout", "bytes": out_bytes, "redacted": bool(redacted)},
            {"artifact_type": "whois_record", "bytes": sum_bytes, "redacted": bool(redacted)},
        ],
        "result": summary,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }

