    try:
        ip_norm = str(ipaddress.ip_address(target.strip()))
    except Exception:
        ip_norm = None
    stdout = "Starting Nmap 7.94 (offline simulation)\n"
    stdout += f"Nmap scan report for {ip_norm or target}\n"
    stdout += "PORT   STATE SERVICE\n"
    stdout += "80/tcp open  http\n"
    stdout += "443/tcp open  https\n"
    stdout += f"\nNote: Offline simulation at {now_iso}\n"

    findings = {
        "target": target,
        "host": ip_norm or target,
