        "content_json": None,
        "content_sha256": _sha256_text(out_text),
        "bytes": out_bytes,
        "redacted": bool(redacted),
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    scan_json = {"findings": findings}
    scan_bytes = len(json.dumps(scan_json, ensure_ascii=False).encode("utf-8"))
    if scan_bytes > 10485760:
        scan_json = {"note": "TRUNCATED: scan_results exceeded 10MB", "target": target}
        scan_bytes = len(json.dumps(scan_json, ensure_ascii=False).encode("utf-8"))
        redacted = True
    artifacts.append({
        "id": _gen_id("osint_art"),
        "tool_run_id": tool_run_id,
        "artifact_type": "scan_results",
        "content_text": None,
        "content_json": scan_json,
        "content_sha256": _sha256_text(json.dumps(scan_json, ensure_ascii=False)),
        "bytes": scan_bytes,
        "redacted": bool(redacted),
        "created_at": now_iso,
        "updated_at": now_iso,
    })

    finished = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    run_row["status"] = "succeeded"
    run_row["finished_at"] = finished.replace(microsecond=0).isoformat().replace("+00:00", "Z")
