                if _count_type(usage_events, cid, "tool_run_created", day_ago) < tool_limit:
                    any_under_quota = True
            if not any_under_rpm:
                return None, _err("RATE_LIMIT", "Requests per minute limit exceeded.")
            return None, _err("QUOTA_EXCEEDED", "Daily tool run quota exceeded.")
        candidates.sort(key=lambda x: (x[0], x[1]))
        return candidates[0][2], None

    # validate
    if not isinstance(target, str) or not target.strip():
        return _err("VALIDATION_ERROR", "target must be a non-empty string")
    if len(target) > 2048:
        return _err("VALIDATION_ERROR", "target length must be between 1 and 2048")

    api_clients = _load("api_clients.json")
    tool_runs = _load("tool_runs.json")
    artifacts = _load("tool_run_artifacts.json")
    usage_events = _load("usage_events.json")

    client, auth_err = _choose_active_client_under_limits(api_clients, usage_events)
    if auth_err:
        return auth_err
    client_id = client["id"]

    started = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    tool_run_id = _gen_id("osint_run")
    run_row = {
        "id": tool_run_id,
        "client_id": client_id,
        "investigation_id": None,
        "tool_name": "dig_lookup",
        "input_target": target,
        "input_domain": None,
        "status": "running",
        "exit_code": 0,
        "error_message": None,
        "duration_ms": None,
        "started_at": started.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        "finished_at": None,
        "created_at": started.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        "updated_at": started.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    }
    tool_runs.append(run_row)
    _append_usage(usage_events, client_id, "tool_run_created", tool_run_id=tool_run_id, tool_name="dig_lookup", status="running")

    # offline simulated dig response
    qname = target.strip()
    stdout = f"; <<>> DiG 9.18.24 <<>> {qname}\n;; global options: +cmd\n"
    records = []
    try:
        ip = str(ipaddress.ip_address(qname))
        stdout += f";; ANSWER SECTION:\n{qname}. 300 IN PTR example.local.\n"
        records.append({"name": qname, "type": "PTR", "value": "example.local.", "ttl": 300})
    except Exception:
        if re.match(r"^[A-Za-z0-9.-]+\.[A-Za-z]{2,}$", qname):
            stdout += f";; ANSWER SECTION:\n{qname}. 300 IN A 93.184.216.34\n"
            records.append({"name": qname.lower(), "type": "A", "value": "93.184.216.34", "ttl": 300})
        else:
            stdout += ";; connection timed out; no servers could be reached\n"

    result = {"target": qname, "records": records, "note": "Offline simulation; no external DNS queries executed."}

    out_text, out_bytes, redacted = _truncate_text(stdout)
    artifacts.append({
        "id": _gen_id("osint_art"),
        "tool_run_id": tool_run_id,
        "artifact_type": "stdout",
        "content_text": out_text,
        "content_json": None,
        "content_sha256": _sha256_text(out_text),
        "bytes": out_bytes,
        "redacted": bool(redacted),
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    rec_json = {"dns_records": records}
    rec_bytes = len(json.dumps(rec_json, ensure_ascii=False).encode("utf-8"))
    if rec_bytes > 10485760:
        rec_json = {"note": "TRUNCATED: dns_records exceeded 10MB", "target": qname}
        rec_bytes = len(json.dumps(rec_json, ensure_ascii=False).encode("utf-8"))
        redacted = True
    artifacts.append({
        "id": _gen_id("osint_art"),
        "tool_run_id": tool_run_id,
        "artifact_type": "dns_records",
        "content_text": None,
        "content_json": rec_json,
        "content_sha256": _sha256_text(json.dumps(rec_json, ensure_ascii=False)),
        "bytes": rec_bytes,
        "redacted": bool(redacted),
        "created_at": now_iso,
        "updated_at": now_iso,
    })

    finished = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    run_row["status"] = "succeeded"
    run_row["finished_at"] = finished.replace(microsecond=0).isoformat().replace("+00:00", "Z")
    run_row["duration_ms"] = int(max(0, (finished - started).total_seconds() * 1000))
    run_row["updated_at"] = run_row["finished_at"]
    _append_usage(usage_events, client_id, "tool_run_completed", tool_run_id=tool_run_id, tool_name="dig_lookup", status="succeeded")

    client["last_seen_at"] = now_iso
    client["updated_at"] = now_iso

    _save("tool_runs.json", tool_runs)
    _save("tool_run_artifacts.json", artifacts)
    _save("usage_events.json", usage_events)
    _save("api_clients.json", api_clients)

    return {"tool_run": run_row, "result": result, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def host_lookup(target, **_extra):
    import json, os, datetime, time, uuid, hashlib, re, ipaddress
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0003000" if __import__("os").path.isdir("./environment_mix/0003000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _sha256_text(s):
        if s is None:
            return None
        if not isinstance(s, str):
            s = str(s)
        return hashlib.sha256(s.encode("utf-8", errors="replace")).hexdigest()

    def _truncate_text(text, max_bytes=10485760):
        if text is None:
            return None, 0, False
        if not isinstance(text, str):
            text = str(text)
        b = text.encode("utf-8", errors="replace")
        if len(b) <= max_bytes:
            return text, len(b), False
        b2 = b[:max_bytes]
        t2 = b2.decode("utf-8", errors="ignore")
        final = t2 + "\n[TRUNCATED: output exceeded 10MB]"
        return final, len(final.encode("utf-8", errors="replace")), True

    def _append_usage(events, client_id, event_type, investigation_id=None, tool_run_id=None, tool_name=None, status=None):
        ts = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        row = {
            "id": _gen_id("osint_ue"),
            "client_id": client_id,
            "event_type": event_type,
            "investigation_id": investigation_id,
            "tool_run_id": tool_run_id,
            "tool_name": tool_name,
            "occurred_at": ts.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "meta": {"endpoint": "host_lookup", "status": status} if status else {"endpoint": "host_lookup"},
            "created_at": ts.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "updated_at": ts.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        }
        events.append(row)
        return row

    def _rpm_count(events, client_id, since_dt):
        c = 0
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_id:
                continue
            odt = _parse_dt(e.get("occurred_at"))
            if odt and odt >= since_dt:
                c += 1
        return c

    def _count_type(events, client_id, event_type, since_dt):
        c = 0
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_id or e.get("event_type") != event_type:
                continue
            odt = _parse_dt(e.get("occurred_at"))
            if odt and odt >= since_dt:
                c += 1
        return c

    def _choose_active_client_under_limits(api_clients, usage_events):
        now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        minute_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(hours=24)
        candidates = []
        for c in api_clients:
            if not isinstance(c, dict) or c.get("status") != "active":
                continue
            cid = c.get("id")
            if not isinstance(cid, str) or not cid:
                continue
            rpm_limit = c.get("requests_per_minute_limit")
            tool_limit = c.get("daily_tool_run_limit")
            if not isinstance(rpm_limit, int) or rpm_limit < 1:
                continue
            if not isinstance(tool_limit, int) or tool_limit < 0:
                continue
            rpm = _rpm_count(usage_events, cid, minute_ago)
            tool_created_24h = _count_type(usage_events, cid, "tool_run_created", day_ago)
            if rpm >= rpm_limit:
                continue
            if tool_created_24h >= tool_limit:
                continue
            candidates.append((rpm, tool_created_24h, c))
        if not candidates:
            actives = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active"]
            if not actives:
                return None, _err("UNAUTHORIZED", "No active API client is available to serve this request.")
            any_under_rpm = False
            any_under_quota = False
            minute_ago = now_dt - datetime.timedelta(minutes=1)
            day_ago = now_dt - datetime.timedelta(hours=24)
            for c in actives:
                cid = c.get("id")
                rpm_limit = c.get("requests_per_minute_limit")
                tool_limit = c.get("daily_tool_run_limit")
                if not isinstance(cid, str) or not isinstance(rpm_limit, int) or not isinstance(tool_limit, int):
                    continue
                if _rpm_count(usage_events, cid, minute_ago) < rpm_limit:
                    any_under_rpm = True
                if _count_type(usage_events, cid, "tool_run_created", day_ago) < tool_limit:
                    any_under_quota = True
            if not any_under_rpm:
                return None, _err("RATE_LIMIT", "Requests per minute limit exceeded.")
            return None, _err("QUOTA_EXCEEDED", "Daily tool run quota exceeded.")
        candidates.sort(key=lambda x: (x[0], x[1]))
        return candidates[0][2], None

    # validate
    if not isinstance(target, str) or not target.strip():
        return _err("VALIDATION_ERROR", "target must be a non-empty string")
    if len(target) > 2048:
        return _err("VALIDATION_ERROR", "target length must be between 1 and 2048")

    api_clients = _load("api_clients.json")
    tool_runs = _load("tool_runs.json")
    artifacts = _load("tool_run_artifacts.json")
    usage_events = _load("usage_events.json")

    client, auth_err = _choose_active_client_under_limits(api_clients, usage_events)
    if auth_err:
        return auth_err
    client_id = client["id"]

    started = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    tool_run_id = _gen_id("osint_run")
    run_row = {
        "id": tool_run_id,
        "client_id": client_id,
        "investigation_id": None,
        "tool_name": "host_lookup",
        "input_target": target,
        "input_domain": None,
        "status": "running",
        "exit_code": 0,
        "error_message": None,
        "duration_ms": None,
        "started_at": started.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        "finished_at": None,
        "created_at": started.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        "updated_at": started.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
    }
    tool_runs.append(run_row)
    _append_usage(usage_events, client_id, "tool_run_created", tool_run_id=tool_run_id, tool_name="host_lookup", status="running")

    tgt = target.strip()
    stdout = f"host (offline simulation) {tgt}\n"
    resolution = {"target": tgt, "forward": [], "reverse": [], "note": "Offline simulation; no real resolution executed."}
    try:
        ip = str(ipaddress.ip_address(tgt))
        stdout += f"{tgt}.in-addr.arpa domain name pointer example.local.\n"
        resolution["reverse"].append({"ip": ip, "ptr": "example.local."})
    except Exception:
        if re.match(r"^[A-Za-z0-9.-]+\.[A-Za-z]{2,}$", tgt):
            stdout += f"{tgt} has address 93.184.216.34\n"
            resolution["forward"].append({"name": tgt.lower(), "address": "93.184.216.34"})
        else:
            stdout += "Host not found: 3(NXDOMAIN)\n"

    out_text, out_bytes, redacted = _truncate_text(stdout)
    artifacts.append({
        "id": _gen_id("osint_art"),
        "tool_run_id": tool_run_id,
        "artifact_type": "stdout",
        "content_text": out_text,
        "content_json": None,
        "content_sha256": _sha256_text(out_text),
        "bytes": out_bytes,
        "redacted": bool(redacted),
        "created_at": now_iso,
        "updated_at": now_iso,
    })
    res_json = {"host_resolution": resolution}
    res_bytes = len(json.dumps(res_json, ensure_ascii=False).encode("utf-8"))
    if res_bytes > 10485760:
        res_json = {"note": "TRUNCATED: host_resolution exceeded 10MB", "target": tgt}
        res_bytes = len(json.dumps(res_json, ensure_ascii=False).encode("utf-8"))
        redacted = True
    artifacts.append({
        "id": _gen_id("osint_art"),
        "tool_run_id": tool_run_id,
        "artifact_type": "host_resolution",
        "content_text": None,
        "content_json": res_json,
        "content_sha256": _sha256_text(json.dumps(res_json, ensure_ascii=False)),
        "bytes": res_bytes,
        "redacted": bool(redacted),
        "created_at": now_iso,
        "updated_at": now_iso,
    })

    finished = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    run_row["status"] = "succeeded"
    run_row["finished_at"] = finished.replace(microsecond=0).isoformat().replace("+00:00", "Z")
    run_row["duration_ms"] = int(max(0, (finished - started).total_seconds() * 1000))
    run_row["updated_at"] = run_row["finished_at"]
    _append_usage(usage_events, client_id, "tool_run_completed", tool_run_id=tool_run_id, tool_name="host_lookup", status="succeeded")

    client["last_seen_at"] = now_iso
    client["updated_at"] = now_iso

    _save("tool_runs.json", tool_runs)
    _save("tool_run_artifacts.json", artifacts)
    _save("usage_events.json", usage_events)
    _save("api_clients.json", api_clients)

    return {"tool_run": run_row, "result": resolution, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def osint_overview(target, **_extra):
    import json, os, datetime, time, re, uuid, subprocess, hashlib, ipaddress
    from urllib.parse import urlparse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0003000" if __import__("os").path.isdir("./environment_mix/0003000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    if not isinstance(target, str):
        return _err("VALIDATION_ERROR", "target must be a string")
    if not target.strip():
        return _err("VALIDATION_ERROR", "target must be a non-empty string")
    if len(target) > 2048:
        return _err("VALIDATION_ERROR", "target length must be between 1 and 2048")

    api_clients = _load("api_clients.json")
    investigations = _load("investigations.json")
    tool_runs = _load("tool_runs.json")
    artifacts = _load("tool_run_artifacts.json")
    usage = _load("usage_events.json")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _rpm_count(evts, client_id, since_dt):
        c = 0
        for e in evts:
            if e.get("client_id") != client_id:
                continue
            odt = _parse_dt(e.get("occurred_at"))
            if odt and odt >= since_dt:
                c += 1
        return c

    def _count_type(evts, client_id, etype, since_dt):
        c = 0
        for e in evts:
            if e.get("client_id") != client_id:
                continue
            if e.get("event_type") != etype:
                continue
            odt = _parse_dt(e.get("occurred_at"))
            if odt and odt >= since_dt:
                c += 1
        return c

    minute_ago = now - datetime.timedelta(minutes=1)
    day_ago = now - datetime.timedelta(hours=24)

    # Determine default toolset per business rule (excluding osint_overview itself)
    default_toolset = ["whois_lookup", "nmap_scan", "dnsrecon_lookup", "dnstwist_lookup", "dig_lookup", "host_lookup"]

    # auth ambient: choose an active client that can create 1 investigation + (1 parent run + N child runs) tool runs within quotas
    def _can_client(c, needed_inv, needed_tr):
        if c.get("status") != "active":
            return False, "inactive"
        rpm_limit = c.get("requests_per_minute_limit")
        if not isinstance(rpm_limit, int) or rpm_limit < 1:
            return False, "bad_rpm"
        if _rpm_count(usage, c.get("id"), minute_ago) >= rpm_limit:
            return False, "rate"

        inv_limit = c.get("daily_investigation_limit")
        tr_limit = c.get("daily_tool_run_limit")
        if not isinstance(inv_limit, int) or inv_limit < 0:
            return False, "bad_inv_limit"
        if not isinstance(tr_limit, int) or tr_limit < 0:
            return False, "bad_tr_limit"

        inv_used = _count_type(usage, c.get("id"), "investigation_created", day_ago)
        tr_used = _count_type(usage, c.get("id"), "tool_run_created", day_ago)
        if inv_used + needed_inv > inv_limit:
            return False, "inv_quota"
        if tr_used + needed_tr > tr_limit:
            return False, "tr_quota"
        return True, None

    needed_investigations = 1
    needed_tool_runs = 1 + len(default_toolset)  # parent + children
    chosen = None
    reason = None
    for c in api_clients:
        ok, r = _can_client(c, needed_investigations, needed_tool_runs)
        if ok:
            chosen = c
            break
        reason = r

    if not chosen:
        any_active = any(c.get("status") == "active" for c in api_clients)
        if any_active and reason in ("inv_quota", "tr_quota"):
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for overview generation")
        if any_active and reason == "rate":
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return _err("UNAUTHORIZED", "No active API client context available for this request")

    client_id = chosen.get("id")

    # ---- target classification + canonical_domain derivation ----
    def _is_ip(s):
        try:
            ipaddress.ip_address(s)
            return True
        except Exception:
            return False

    def _canonical_domain_from_target(t):
        tt = t.strip()
        # URL
        if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", tt):
            try:
                u = urlparse(tt)
                host = (u.hostname or "").strip().lower()
                if host:
                    return host, "url"
            except Exception:
                pass
        # email not supported by investigations schema enum; map to unknown
        if "@" in tt and re.match(r"^[^@\s]{1,64}@[^@\s]{1,255}$", tt):
            dom = tt.split("@", 1)[1].strip().lower().strip(".")
            if dom:
                return dom, "unknown"
        # ip
        if _is_ip(tt):
            return None, "ip"
        # hostname / domain
        host = tt.lower()
        host = host.split("/")[0]
        host = host.split(":")[0]
        host = host.strip(".")
        if host and re.match(r"^[a-z0-9._-]{1,253}$", host):
            # crude: if contains at least one dot and last label alpha-ish => domain else hostname
            labels = host.split(".")
            if len(labels) >= 2 and all(labels):
                return host, "domain"
            return host, "hostname"
        return None, "unknown"

    canonical_domain, ttype = _canonical_domain_from_target(target)
    if canonical_domain is not None and (len(canonical_domain) < 1 or len(canonical_domain) > 253):
        return _err("VALIDATION_ERROR", "Derived canonical_domain length must be between 1 and 253")

    # ---- helpers ----
    def _new_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    def _add_usage(event_type, investigation_id=None, tool_run_id=None, tool_name=None, meta=None):
        usage.append({
            "id": _new_id("ue"),
            "client_id": client_id,
            "event_type": event_type,
            "investigation_id": investigation_id,
            "tool_run_id": tool_run_id,
            "tool_name": tool_name,
            "occurred_at": now_iso,
            "meta": meta if isinstance(meta, dict) else None,
            "created_at": now_iso,
            "updated_at": now_iso,
        })

    def _truncate_bytes(data_bytes, limit=10485760):
        if len(data_bytes) <= limit:
            return data_bytes, False
        return data_bytes[:limit], True

    def _sha256_hex(b):
        return hashlib.sha256(b).hexdigest()

    def _upsert_artifact(tool_run_id, artifact_type, content_text=None, content_json=None, ts_iso=None):
        if content_text is None and content_json is None:
            return False, _err("VALIDATION_ERROR", "artifact must have content_text or content_json")
        if ts_iso is None:
            ts_iso = now_iso

        existing = None
        for a in artifacts:
            if a.get("tool_run_id") == tool_run_id and a.get("artifact_type") == artifact_type:
                existing = a
                break

        redacted = False
        note = None
        raw_bytes = b""
        if content_json is not None:
            raw_bytes = json.dumps(content_json, ensure_ascii=False).encode("utf-8", errors="replace")
        else:
            raw_bytes = (content_text or "").encode("utf-8", errors="replace")

        raw_bytes_trunc, truncated = _truncate_bytes(raw_bytes, 10485760)
        if truncated:
            redacted = True
            note = "Output truncated due to 10MB artifact limit"
            if content_json is not None:
                content_json = {"note": note, "truncated": True, "preview": raw_bytes_trunc.decode("utf-8", errors="replace")}
                content_text = None
            else:
                content_text = raw_bytes_trunc.decode("utf-8", errors="replace") + "\n\n[TRUNCATED: 10MB limit]"
                content_json = {"note": note, "truncated": True}

        bytes_count = len(raw_bytes_trunc)
        sha = _sha256_hex(raw_bytes_trunc)

        if existing is None:
            artifacts.append({
                "id": _new_id("art"),
                "tool_run_id": tool_run_id,
                "artifact_type": artifact_type,
                "content_text": content_text,
                "content_json": content_json,
                "content_sha256": sha,
                "bytes": bytes_count,
                "redacted": bool(redacted),
                "created_at": ts_iso,
                "updated_at": ts_iso,
            })
        else:
            existing["content_text"] = content_text
            existing["content_json"] = content_json
            existing["content_sha256"] = sha
            existing["bytes"] = bytes_count
            existing["redacted"] = bool(redacted)
            existing["updated_at"] = ts_iso
        return True, None

    # ---- create investigation ----
    inv_id = _new_id("inv")
    inv = {
        "id": inv_id,
        "client_id": client_id,
        "target": target,
        "target_type": ttype if ttype in ("domain", "ip", "hostname", "url", "unknown") else "unknown",
        "canonical_domain": canonical_domain,
        "status": "queued",
        "error_message": None,
        "requested_toolset": default_toolset,  # empty means default; but we store explicit default for auditability
        "started_at": None,
        "completed_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    investigations.append(inv)
    _add_usage("investigation_created", investigation_id=inv_id)

    # ---- parent tool run: osint_overview ----
    parent_tr_id = _new_id("tr")
    parent_tr = {
        "id": parent_tr_id,
        "client_id": client_id,
        "investigation_id": inv_id,
        "tool_name": "osint_overview",
        "input_target": target,
        "input_domain": None,
        "status": "queued",
        "exit_code": None,
        "error_message": None,
        "duration_ms": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    tool_runs.append(parent_tr)
    _add_usage("tool_run_created", tool_run_id=parent_tr_id, tool_name="osint_overview")

    # Start investigation + parent run
    inv["status"] = "running"
    inv["started_at"] = now_iso
    inv["updated_at"] = now_iso
    parent_tr["status"] = "running"
    parent_tr["started_at"] = now_iso
    parent_tr["updated_at"] = now_iso

    # ---- create child tool runs and execute subset we can (dig/host). Others succeed with placeholder output. ----
    child_runs = []
    errors = []

    def _run_command(cmd, timeout_s=15):
        try:
            p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_s)
            return p.returncode, (p.stdout or ""), (p.stderr or ""), False
        except FileNotFoundError:
            return 127, "", f"{cmd[0]} not available on this system", False
        except subprocess.TimeoutExpired as e:
            return -1, (e.stdout or "") if isinstance(e.stdout, str) else "", (e.stderr or "") if isinstance(e.stderr, str) else f"{cmd[0]} timed out", True
        except Exception as e:
            return 1, "", f"{cmd[0]} execution error: {e}", False

    def _finalize_run(tr, finished_iso, duration_ms, exit_code, timed_out, err_msg=None):
        tr["exit_code"] = exit_code
        tr["duration_ms"] = duration_ms
        tr["finished_at"] = finished_iso
        tr["updated_at"] = finished_iso
        if timed_out:
            tr["status"] = "timed_out"
            tr["error_message"] = err_msg or "timed out"
            _add_usage("tool_run_failed", tool_run_id=tr["id"], tool_name=tr["tool_name"], meta={"reason": "timeout"})
        elif exit_code != 0:
            tr["status"] = "failed"
            tr["error_message"] = (err_msg or "tool failed")[:4000]
            _add_usage("tool_run_failed", tool_run_id=tr["id"], tool_name=tr["tool_name"], meta={"exit_code": exit_code})
        else:
            tr["status"] = "succeeded"
            _add_usage("tool_run_completed", tool_run_id=tr["id"], tool_name=tr["tool_name"])

    for tool in default_toolset:
        tr_id = _new_id("tr")
        child = {
            "id": tr_id,
            "client_id": client_id,
            "investigation_id": inv_id,
            "tool_name": tool,
            "input_target": None,
            "input_domain": None,
            "status": "queued",
            "exit_code": None,
            "error_message": None,
            "duration_ms": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }

        # input mapping constraint
        if tool == "dnstwist_lookup":
            child["input_domain"] = canonical_domain if canonical_domain else None
            child["input_target"] = None
            if child["input_domain"] is None:
                # Cannot run dnstwist without domain; fail fast but still store artifacts
                tool_runs.append(child)
                _add_usage("tool_run_created", tool_run_id=tr_id, tool_name=tool)
                child["status"] = "running"
                child["started_at"] = now_iso
                child["updated_at"] = now_iso
                finished_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _finalize_run(child, finished_iso, 0, 1, False, "dnstwist requires a domain-derived canonical_domain")
                _upsert_artifact(tr_id, "stderr", content_text="dnstwist requires a domain-derived canonical_domain", ts_iso=finished_iso)
                child_runs.append(child)
                errors.append({"tool_name": tool, "status": child["status"], "message": child["error_message"]})
                continue
        else:
            child["input_target"] = target

        tool_runs.append(child)
        _add_usage("tool_run_created", tool_run_id=tr_id, tool_name=tool)
        child["status"] = "running"
        child["started_at"] = now_iso
        child["updated_at"] = now_iso

        start = time.time()
        stdout_text = ""
        stderr_text = ""
        exit_code = 0
        timed_out = False
        parsed = None

        if tool == "dig_lookup":
            exit_code, stdout_text, stderr_text, timed_out = _run_command(["dig", "+noall", "+answer", "+comments", target], timeout_s=15)
            # parse records
            recs = []
            for line in (stdout_text or "").splitlines():
                line = line.strip()
                if not line or line.startswith(";"):
                    continue
                parts = re.split(r"\s+", line)
                if len(parts) >= 5:
                    name, ttl, rrclass, rrtype = parts[0], parts[1], parts[2], parts[3]
                    rdata = " ".join(parts[4:])
                    try:
                        ttl_i = int(ttl)
                    except Exception:
                        ttl_i = None
                    recs.append({"name": name.rstrip("."), "ttl": ttl_i, "class": rrclass, "type": rrtype, "data": rdata.rstrip(".")})
            parsed = {"records": recs}
            _upsert_artifact(tr_id, "dns_records", content_json=parsed, ts_iso=now_iso)
        elif tool == "host_lookup":
            exit_code, stdout_text, stderr_text, timed_out = _run_command(["host", target], timeout_s=15)
            resolutions = {"a": [], "aaaa": [], "ptr": [], "cname": [], "mx": []}
            for line in (stdout_text or "").splitlines():
                s = line.strip()
                if not s:
                    continue
                m = re.search(r"\bhas address\b\s+([0-9.]+)\b", s)
                if m:
                    resolutions["a"].append(m.group(1)); continue
                m = re.search(r"\bhas IPv6 address\b\s+([0-9a-fA-F:]+)\b", s)
                if m:
                    resolutions["aaaa"].append(m.group(1)); continue
                m = re.search(r"\bdomain name pointer\b\s+([A-Za-z0-9._-]+)\.?\s*$", s)
                if m:
                    resolutions["ptr"].append(m.group(1).rstrip(".")); continue
                m = re.search(r"\bis an alias for\b\s+([A-Za-z0-9._-]+)\.?\s*$", s)
                if m:
                    resolutions["cname"].append(m.group(1).rstrip(".")); continue
                m = re.search(r"\bmail is handled by\b\s+\d+\s+([A-Za-z0-9._-]+)\.?\s*$", s)
                if m:
                    resolutions["mx"].append(m.group(1).rstrip(".")); continue
            parsed = {"resolutions": resolutions}
            _upsert_artifact(tr_id, "host_resolution", content_json=parsed, ts_iso=now_iso)
        else:
            # Placeholder for tools not implemented in this service batch; succeed with note.
            exit_code = 0
            stdout_text = f"{tool} execution is not available in this deployment; placeholder result recorded."
            parsed = {"note": "placeholder", "tool": tool}

        finished_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        duration_ms = int(max(0, (time.time() - start) * 1000))
        _finalize_run(child, finished_iso, duration_ms, exit_code, timed_out, err_msg=(stderr_text or "").strip() or None)

        # Must store at least one artifact per run
        _upsert_artifact(tr_id, "stdout", content_text=stdout_text, ts_iso=finished_iso)
        if (stderr_text or "").strip():
            _upsert_artifact(tr_id, "stderr", content_text=stderr_text, ts_iso=finished_iso)
        if parsed is not None and tool not in ("dig_lookup", "host_lookup"):
            _upsert_artifact(tr_id, "parsed_summary", content_json=parsed, ts_iso=finished_iso)

        child_runs.append(child)
        if child["status"] in ("failed", "timed_out"):
            errors.append({"tool_name": tool, "status": child["status"], "message": child.get("error_message")})

    # ---- Build overview report artifact on parent run ----
    # Parent report references child tool_run ids and high-level status.
    report = {
        "target": target,
        "target_type": inv["target_type"],
        "canonical_domain": canonical_domain,
        "investigation_id": inv_id,
        "parent_tool_run_id": parent_tr_id,
        "child_tool_runs": [{"tool_name": r["tool_name"], "tool_run_id": r["id"], "status": r["status"]} for r in child_runs],
        "errors": errors,
        "generated_at": now_iso,
    }
    _upsert_artifact(parent_tr_id, "overview_report", content_json=report, ts_iso=now_iso)

    # finalize parent and investigation
    parent_finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    parent_tr["finished_at"] = parent_finished
    parent_tr["duration_ms"] = int(max(0, (time.time() - t0) * 1000))
    parent_tr["updated_at"] = parent_finished

    # Determine overall success: if any child failed/timed_out -> parent failed, investigation failed; else succeeded/completed
    if any(r["status"] in ("failed", "timed_out") for r in child_runs):
        parent_tr["status"] = "failed"
        parent_tr["error_message"] = "One or more child tool runs failed"
        parent_tr["exit_code"] = 1
        _add_usage("tool_run_failed", tool_run_id=parent_tr_id, tool_name="osint_overview", meta={"child_failures": len(errors)})

        inv["status"] = "failed"
        inv["error_message"] = "One or more tools failed during overview"
    else:
        parent_tr["status"] = "succeeded"
        parent_tr["exit_code"] = 0
        _add_usage("tool_run_completed", tool_run_id=parent_tr_id, tool_name="osint_overview")

        inv["status"] = "completed"
        inv["error_message"] = None

    inv["completed_at"] = parent_finished
    inv["updated_at"] = parent_finished

    chosen["last_seen_at"] = parent_finished
    chosen["updated_at"] = parent_finished

    _save("api_clients.json", api_clients)
    _save("investigations.json", investigations)
    _save("tool_runs.json", tool_runs)
    _save("tool_run_artifacts.json", artifacts)
    _save("usage_events.json", usage)

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    return {
        "investigation": inv,
        "parent_tool_run": parent_tr,
        "child_tool_runs": child_runs,
        "overview_report": report,
        "meta": {"latency_ms": latency_ms},
    }

def list_investigations(api_key, status=None, target=None, target_type=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0003000" if __import__("os").path.isdir("./environment_mix/0003000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "completed", "failed", "cancelled"):
            return _err("VALIDATION_ERROR", "status must be one of: queued, running, completed, failed, cancelled")
    if target is not None:
        if not isinstance(target, str):
            return _err("VALIDATION_ERROR", "target must be a string")
        if len(target) > 2048:
            return _err("VALIDATION_ERROR", "target length must be between 1 and 2048")
    if target_type is not None:
        if not isinstance(target_type, str):
            return _err("VALIDATION_ERROR", "target_type must be a string")
        # Tool enum includes 'email' but investigations schema doesn't; still allow filter by email but it will match none.
        if target_type not in ("domain", "ip", "url", "hostname", "email", "unknown"):
            return _err("VALIDATION_ERROR", "target_type must be one of: domain, ip, url, hostname, email, unknown")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    def _parse_dt_param(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be an RFC3339 date-time string")

    ca = _parse_dt_param(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        return ca
    cb = _parse_dt_param(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        return cb

    api_clients = _load("api_clients.json")
    investigations = _load("investigations.json")
    usage = _load("usage_events.json")

    # Authenticate by matching api_key to stored api_key_hash OR id (per rules: never compare to plaintext behind hash)
    client = None
    for c in api_clients:
        if api_key == c.get("id") or api_key == c.get("api_key_hash"):
            client = c
            break
    if not client:
        return _err("UNAUTHORIZED", "Invalid API key")
    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "API client is not active")

    # Enforce rate limit based on usage_events.occurred_at (all events)
    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    minute_ago = now - datetime.timedelta(minutes=1)
    rpm_used = 0
    for e in usage:
        if e.get("client_id") != client.get("id"):
            continue
        odt = _parse_dt(e.get("occurred_at"))
        if odt and odt >= minute_ago:
            rpm_used += 1
    rpm_limit = client.get("requests_per_minute_limit")
    if isinstance(rpm_limit, int) and rpm_used >= rpm_limit:
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Cursor handling: opaque base64url of JSON {"created_at": "...", "id": "..."} of last item
    cursor_created_at = None
    cursor_id = None
    if cursor:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8"))
            obj = json.loads(raw.decode("utf-8"))
            cursor_created_at = obj.get("created_at")
            cursor_id = obj.get("id")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    def _created_dt(inv):
        dt = _parse_dt(inv.get("created_at"))
        return dt or datetime.datetime(1970, 1, 1)

    # Filter
    rows = [inv for inv in investigations if inv.get("client_id") == client.get("id")]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if target is not None:
        rows = [r for r in rows if r.get("target") == target]
    if target_type is not None:
        # allow 'email' filter even though none exist
        rows = [r for r in rows if r.get("target_type") == target_type]
    if ca is not None:
        rows = [r for r in rows if _created_dt(r) >= ca]
    if cb is not None:
        rows = [r for r in rows if _created_dt(r) < cb]

    # Sort created_at desc, tie-break by id desc
    rows.sort(key=lambda r: (_created_dt(r), r.get("id") or ""), reverse=True)

    # Apply cursor: return items strictly "after" cursor in this sort order
    if cursor_created_at and cursor_id:
        cdt = _parse_dt(cursor_created_at) or datetime.datetime(1970, 1, 1)
        filtered = []
        for r in rows:
            rdt = _created_dt(r)
            rid = r.get("id") or ""
            # since desc order, items after cursor are those with (rdt, rid) < (cdt, cursor_id)
            if (rdt, rid) < (cdt, cursor_id):
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # Update client last_seen and log an access event as usage (no dedicated request log collection; usage_events is closest)
    client["last_seen_at"] = now_iso
    client["updated_at"] = now_iso
    usage.append({
        "id": "ue_" + hashlib.sha256((now_iso + (client.get("id") or "") + "list_investigations").encode("utf-8")).hexdigest()[:32],
        "client_id": client.get("id"),
        "event_type": "tool_run_completed",  # best-fit audit marker for read access in this schema
        "investigation_id": None,
        "tool_run_id": None,
        "tool_name": "osint_overview",
        "occurred_at": now_iso,
        "meta": {"endpoint": "list_investigations", "status": "ok"},
        "created_at": now_iso,
        "updated_at": now_iso,
    })

    _save("api_clients.json", api_clients)
    _save("usage_events.json", usage)

    latency_ms = int(max(0, (time.time() - t0) * 1000))
    return {
        "data": page,
        "pagination": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
        "meta": {"latency_ms": latency_ms},
    }

def get_investigation(api_key, investigation_id, include_tool_runs=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0003000" if __import__("os").path.isdir("./environment_mix/0003000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _append_usage(client_id, event_type, investigation_id=None, tool_run_id=None, tool_name=None, meta=None):
        usage = _load("usage_events.json")
        if not isinstance(usage, list):
            usage = []
        now_dt = _now()
        eid = f"osint_use_{int(now_dt.timestamp() * 1000)}_{len(usage)+1}"
        row = {
            "id": eid,
            "client_id": client_id,
            "event_type": event_type,
            "investigation_id": investigation_id,
            "tool_run_id": tool_run_id,
            "tool_name": tool_name,
            "occurred_at": _iso(now_dt),
            "meta": meta if isinstance(meta, dict) else None,
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        usage.append(row)
        _save("usage_events.json", usage)

    def _enforce_rpm(client_row):
        # Rate limiting based on usage_events occurred_at for this client
        rpm_limit = client_row.get("requests_per_minute_limit")
        if not isinstance(rpm_limit, int) or rpm_limit < 1:
            # schema says between 1 and 6000; if corrupt, fail closed but with validation-ish error
            return _err("VALIDATION_ERROR", "Client rate limit is misconfigured", client_id=client_row.get("id"))
        usage = _load("usage_events.json")
        if not isinstance(usage, list):
            usage = []
        now_dt = _now()
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        cid = client_row.get("id")
        for ev in usage:
            if not isinstance(ev, dict):
                continue
            if ev.get("client_id") != cid:
                continue
            odt = _parse_dt(ev.get("occurred_at"))
            if odt is None:
                continue
            if odt >= window_start and odt <= now_dt:
                cnt += 1
        if cnt >= rpm_limit:
            return _err("RATE_LIMIT", "Requests per minute limit exceeded", limit=rpm_limit)
        return None

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(investigation_id, str) or not investigation_id.strip():
        return _err("VALIDATION_ERROR", "investigation_id must be a non-empty string", field="investigation_id")
    if include_tool_runs is None:
        include_tool_runs = False
    if not isinstance(include_tool_runs, bool):
        return _err("VALIDATION_ERROR", "include_tool_runs must be a boolean", field="include_tool_runs")

    api_clients = _load("api_clients.json")
    investigations = _load("investigations.json")
    tool_runs = _load("tool_runs.json")

    if not isinstance(api_clients, list):
        api_clients = []
    if not isinstance(investigations, list):
        investigations = []
    if not isinstance(tool_runs, list):
        tool_runs = []

    # Find the investigation (existence is global; authorization is by owning client)
    inv = None
    for r in investigations:
        if isinstance(r, dict) and r.get("id") == investigation_id:
            inv = r
            break
    if inv is None:
        # cannot record usage without a client_id (unknown key), but also don't leak existence
        return _err("NOT_FOUND", "Investigation not found", investigation_id=investigation_id)

    # Authenticate api_key: treat api_key as either api_clients.id or api_clients.api_key_hash (client-visible token in this store)
    candidates = []
    for c in api_clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            candidates.append(c)

    if not candidates:
        return _err("UNAUTHORIZED", "Invalid API key")

    # Choose a candidate that is authorized to access the investigation
    client = None
    for c in candidates:
        if c.get("id") == inv.get("client_id"):
            client = c
            break
    if client is None:
        # Record an audit usage event against the first matching credential (best-effort)
        try:
            _append_usage(candidates[0].get("id"), "tool_run_failed", investigation_id=investigation_id, tool_run_id=None, tool_name=None,
                          meta={"endpoint": "get_investigation", "status": "UNAUTHORIZED"})
        except Exception:
            pass
        return _err("UNAUTHORIZED", "Not permitted to access this investigation", investigation_id=investigation_id)

    # Enforce RPM (reads included)
    rl_err = _enforce_rpm(client)
    if rl_err:
        try:
            _append_usage(client.get("id"), "tool_run_failed", investigation_id=investigation_id,
                          meta={"endpoint": "get_investigation", "status": "RATE_LIMIT"})
        except Exception:
            pass
        return rl_err

    # Record usage event for this request (using tool_run_completed as generic request audit)
    try:
        _append_usage(client.get("id"), "tool_run_completed", investigation_id=investigation_id,
                      meta={"endpoint": "get_investigation", "status": "OK", "latency_ms": int((time.time() - t0) * 1000)})
    except Exception:
        pass

    # Update last_seen_at for successful call
    now_dt = _now()
    client_updated = False
    for i, c in enumerate(api_clients):
        if isinstance(c, dict) and c.get("id") == client.get("id"):
            api_clients[i] = dict(c)
            api_clients[i]["last_seen_at"] = _iso(now_dt)
            api_clients[i]["updated_at"] = _iso(now_dt)
            client_updated = True
            break
    if client_updated:
        _save("api_clients.json", api_clients)

    # Build response
    out = dict(inv)
    if include_tool_runs:
        trs = []
        for tr in tool_runs:
            if not isinstance(tr, dict):
                continue
            if tr.get("investigation_id") == investigation_id and tr.get("client_id") == client.get("id"):
                # metadata only (no artifacts)
                trs.append(tr)
        # Sort: created_at asc if present else id
        def _sort_key(x):
            dt = _parse_dt(x.get("created_at"))
            return (dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), x.get("id") or "")
        trs.sort(key=_sort_key)
        out["tool_runs"] = trs

    return {
        "investigation": out,
        "meta": {
            "include_tool_runs": include_tool_runs,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def cancel_investigation(api_key, investigation_id, reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0003000" if __import__("os").path.isdir("./environment_mix/0003000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _append_usage(client_id, event_type, investigation_id=None, tool_run_id=None, tool_name=None, meta=None):
        usage = _load("usage_events.json")
        if not isinstance(usage, list):
            usage = []
        now_dt = _now()
        eid = f"osint_use_{int(now_dt.timestamp() * 1000)}_{len(usage)+1}"
        row = {
            "id": eid,
            "client_id": client_id,
            "event_type": event_type,
            "investigation_id": investigation_id,
            "tool_run_id": tool_run_id,
            "tool_name": tool_name,
            "occurred_at": _iso(now_dt),
            "meta": meta if isinstance(meta, dict) else None,
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        usage.append(row)
        _save("usage_events.json", usage)

    def _enforce_rpm(client_row):
        rpm_limit = client_row.get("requests_per_minute_limit")
        if not isinstance(rpm_limit, int) or rpm_limit < 1:
            return _err("VALIDATION_ERROR", "Client rate limit is misconfigured", client_id=client_row.get("id"))
        usage = _load("usage_events.json")
        if not isinstance(usage, list):
            usage = []
        now_dt = _now()
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        cid = client_row.get("id")
        for ev in usage:
            if not isinstance(ev, dict):
                continue
            if ev.get("client_id") != cid:
                continue
            odt = _parse_dt(ev.get("occurred_at"))
            if odt is None:
                continue
            if odt >= window_start and odt <= now_dt:
                cnt += 1
        if cnt >= rpm_limit:
            return _err("RATE_LIMIT", "Requests per minute limit exceeded", limit=rpm_limit)
        return None

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if not isinstance(investigation_id, str) or not investigation_id.strip():
        return _err("VALIDATION_ERROR", "investigation_id must be a non-empty string", field="investigation_id")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string", field="reason")

    api_clients = _load("api_clients.json")
    investigations = _load("investigations.json")
    tool_runs = _load("tool_runs.json")

    if not isinstance(api_clients, list):
        api_clients = []
    if not isinstance(investigations, list):
        investigations = []
    if not isinstance(tool_runs, list):
        tool_runs = []

    # Locate investigation
    inv_idx = None
    inv = None
    for i, r in enumerate(investigations):
        if isinstance(r, dict) and r.get("id") == investigation_id:
            inv_idx = i
            inv = r
            break
    if inv is None:
        return _err("NOT_FOUND", "Investigation not found", investigation_id=investigation_id)

    # Authenticate api_key (api_key is compared against id or api_key_hash as stored identifier)
    candidates = []
    for c in api_clients:
        if not isinstance(c, dict):
            continue
        if c.get("id") == api_key or c.get("api_key_hash") == api_key:
            candidates.append(c)
    if not candidates:
        return _err("UNAUTHORIZED", "Invalid API key")

    # Authorize against owning client
    client = None
    for c in candidates:
        if c.get("id") == inv.get("client_id"):
            client = c
            break
    if client is None:
        try:
            _append_usage(candidates[0].get("id"), "tool_run_failed", investigation_id=investigation_id,
                          meta={"endpoint": "cancel_investigation", "status": "UNAUTHORIZED"})
        except Exception:
            pass
        return _err("UNAUTHORIZED", "Not permitted to cancel this investigation", investigation_id=investigation_id)

    # Enforce RPM (mutations included)
    rl_err = _enforce_rpm(client)
    if rl_err:
        try:
            _append_usage(client.get("id"), "tool_run_failed", investigation_id=investigation_id,
                          meta={"endpoint": "cancel_investigation", "status": "RATE_LIMIT"})
        except Exception:
            pass
        return rl_err

    # Cancellation state rules
    status = inv.get("status")
    if status not in ("queued", "running", "completed", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "Investigation status is invalid", investigation_id=investigation_id, status=status)

    if status in ("completed", "failed", "cancelled"):
        # Tool description says INVALID_STATE; contract codes allow INVALID_TRANSITION
        try:
            _append_usage(client.get("id"), "tool_run_failed", investigation_id=investigation_id,
                          meta={"endpoint": "cancel_investigation", "status": "INVALID_TRANSITION", "from": status, "to": "cancelled"})
        except Exception:
            pass
        return _err("INVALID_TRANSITION", "Cancellation is not allowed for investigations in a terminal state", investigation_id=investigation_id, status=status)

    # Apply transition to cancelled (queued/running -> cancelled)
    now_dt = _now()
    updated_inv = dict(inv)
    updated_inv["status"] = "cancelled"
    updated_inv["updated_at"] = _iso(now_dt)
    if updated_inv.get("completed_at") is None:
        # best-effort: mark completion moment at cancellation
        updated_inv["completed_at"] = _iso(now_dt)
    if reason is not None and reason.strip():
        # store in error_message field as cancellation reason (schema has no cancel_reason)
        updated_inv["error_message"] = f"cancelled: {reason.strip()}"
    else:
        updated_inv["error_message"] = "cancelled by client request"

    investigations[inv_idx] = updated_inv

    # Attempt to cancel any queued/running tool runs for this investigation
    tr_changed = 0
    tool_run_ids_cancelled = []
    for i, tr in enumerate(tool_runs):
        if not isinstance(tr, dict):
            continue
        if tr.get("client_id") != client.get("id"):
            continue
        if tr.get("investigation_id") != investigation_id:
            continue
        tr_status = tr.get("status")
        if tr_status not in ("queued", "running"):
            continue
        # status transition allowed: queued->cancelled, running->cancelled
        now2 = now_dt
        tr2 = dict(tr)
        tr2["status"] = "cancelled"
        tr2["updated_at"] = _iso(now2)
        if tr_status == "queued":
            # if never started, set started_at/finished_at both to now for terminal-state requirement
            if tr2.get("started_at") is None:
                tr2["started_at"] = _iso(now2)
        if tr2.get("finished_at") is None:
            tr2["finished_at"] = _iso(now2)
        # ensure duration_ms set for terminal state
        sdt = _parse_dt(tr2.get("started_at"))
        if sdt is None:
            sdt = now2
            tr2["started_at"] = _iso(now2)
        dur = int(max(0, (now2 - sdt).total_seconds() * 1000))
        tr2["duration_ms"] = dur
        if tr2.get("exit_code") is None:
            tr2["exit_code"] = -1
        msg = "cancelled due to investigation cancellation"
        if reason is not None and reason.strip():
            msg = msg + f": {reason.strip()}"
        tr2["error_message"] = msg
        tool_runs[i] = tr2
        tr_changed += 1
        if tr2.get("id"):
            tool_run_ids_cancelled.append(tr2.get("id"))
        try:
            _append_usage(client.get("id"), "tool_run_failed", investigation_id=investigation_id, tool_run_id=tr2.get("id"), tool_name=tr2.get("tool_name"),
                          meta={"endpoint": "cancel_investigation", "status": "OK", "cancelled": True})
        except Exception:
            pass

    # Persist changes
    _save("investigations.json", investigations)
    _save("tool_runs.json", tool_runs)

    # Record usage for cancellation request itself (generic request audit)
    try:
        _append_usage(client.get("id"), "tool_run_completed", investigation_id=investigation_id,
                      meta={"endpoint": "cancel_investigation", "status": "OK", "latency_ms": int((time.time() - t0) * 1000), "tool_runs_cancelled": tr_changed})
    except Exception:
        pass

    # Update last_seen_at for successful call
    client_updated = False
    for i, c in enumerate(api_clients):
        if isinstance(c, dict) and c.get("id") == client.get("id"):
            api_clients[i] = dict(c)
            api_clients[i]["last_seen_at"] = _iso(now_dt)
            api_clients[i]["updated_at"] = _iso(now_dt)
            client_updated = True
            break
    if client_updated:
        _save("api_clients.json", api_clients)

    return {
        "investigation": updated_inv,
        "cancelled_tool_runs": tool_run_ids_cancelled,
        "meta": {
            "tool_runs_cancelled_count": tr_changed,
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def list_tool_runs(api_key, investigation_id=None, tool_name=None, status=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0003000" if __import__("os").path.isdir("./environment_mix/0003000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if investigation_id is not None and (not isinstance(investigation_id, str) or not investigation_id.strip()):
        return _err("VALIDATION_ERROR", "investigation_id must be a non-empty string when provided")
    allowed_tools = {"whois_lookup", "nmap_scan", "dnsrecon_lookup", "dnstwist_lookup", "dig_lookup", "host_lookup", "osint_overview"}
    if tool_name is not None and tool_name not in allowed_tools:
        return _err("VALIDATION_ERROR", "tool_name is invalid", allowed=list(sorted(allowed_tools)))
    allowed_status = {"queued", "running", "succeeded", "failed", "timed_out", "cancelled"}
    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "status is invalid", allowed=list(sorted(allowed_status)))
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")

    def _parse_dt_strict(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(field)
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            raise ValueError(field)

    try:
        dt_after = _parse_dt_strict(created_after, "created_after") if created_after is not None else None
    except ValueError:
        return _err("VALIDATION_ERROR", "created_after must be RFC3339 date-time")
    try:
        dt_before = _parse_dt_strict(created_before, "created_before") if created_before is not None else None
    except ValueError:
        return _err("VALIDATION_ERROR", "created_before must be RFC3339 date-time")

    api_clients = _load("api_clients.json")
    tool_runs = _load("tool_runs.json")
    usage_events = _load("usage_events.json")

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # auth
    client = None
    for c in api_clients:
        if isinstance(c, dict) and (c.get("id") == api_key or c.get("api_key_hash") == api_key):
            client = c
            break
    if client is None:
        derived = hashlib.sha256(api_key.encode("utf-8")).hexdigest()
        for c in api_clients:
            if isinstance(c, dict) and c.get("api_key_hash") == derived:
                client = c
                break
    if client is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    client_id = client.get("id")
    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active")

    # rate limit
    rpm_limit = client.get("requests_per_minute_limit")
    if not isinstance(rpm_limit, int) or rpm_limit < 1:
        return _err("UNAUTHORIZED", "Client misconfigured (requests_per_minute_limit)")
    window_start = now - datetime.timedelta(minutes=1)
    cnt = 0
    for e in usage_events:
        if isinstance(e, dict) and e.get("client_id") == client_id:
            dt = _parse_dt(e.get("occurred_at"))
            if dt and dt >= window_start:
                cnt += 1
    if cnt >= rpm_limit:
        ev_id = "ue_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
        ts = now
        usage_events.append({
            "id": ev_id,
            "client_id": client_id,
            "event_type": "tool_run_failed",
            "investigation_id": None,
            "tool_run_id": None,
            "tool_name": "osint_overview",
            "occurred_at": _iso(ts),
            "meta": {"endpoint": "list_tool_runs", "status": "RATE_LIMIT"},
            "created_at": _iso(ts),
            "updated_at": _iso(ts),
        })
        _save("usage_events.json", usage_events)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # cursor decode: base64url(json {"created_at": "...", "id": "..."})
    cursor_created_at = None
    cursor_id = None
    if cursor:
        try:
            pad = "=" * ((4 - (len(cursor) % 4)) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            obj = json.loads(raw)
            cursor_created_at = _parse_dt(obj.get("created_at"))
            cursor_id = obj.get("id")
            if cursor_created_at is None or not isinstance(cursor_id, str):
                return _err("VALIDATION_ERROR", "Invalid cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    # filter runs for client
    rows = []
    for tr in tool_runs:
        if not isinstance(tr, dict):
            continue
        if tr.get("client_id") != client_id:
            continue
        if investigation_id is not None and tr.get("investigation_id") != investigation_id:
            continue
        if tool_name is not None and tr.get("tool_name") != tool_name:
            continue
        if status is not None and tr.get("status") != status:
            continue
        cdt = _parse_dt(tr.get("created_at"))
        if cdt is None:
            # keep but sort to end
            cdt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        if dt_after is not None and cdt < dt_after:
            continue
        if dt_before is not None and cdt >= dt_before:
            continue
        # apply cursor: created_at desc, id desc tie-breaker
        if cursor_created_at is not None:
            tid = tr.get("id")
            if not isinstance(tid, str):
                tid = ""
            if cdt > cursor_created_at:
                continue
            if cdt == cursor_created_at and tid >= cursor_id:
                continue
        rows.append((cdt, tr.get("id") or "", tr))

    rows.sort(key=lambda x: (x[0], x[1]), reverse=True)
    total = len(rows)

    page = rows[:limit]
    out = []
    for _, __, tr in page:
        out.append({
            "id": tr.get("id"),
            "investigation_id": tr.get("investigation_id"),
            "tool_name": tr.get("tool_name"),
            "status": tr.get("status"),
            "input_target": tr.get("input_target"),
            "input_domain": tr.get("input_domain"),
            "exit_code": tr.get("exit_code"),
            "error_message": tr.get("error_message"),
            "duration_ms": tr.get("duration_ms"),
            "started_at": tr.get("started_at"),
            "finished_at": tr.get("finished_at"),
            "created_at": tr.get("created_at"),
            "updated_at": tr.get("updated_at"),
        })

    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last_dt, last_id, _ = page[-1]
        payload = {"created_at": _iso(last_dt), "id": last_id}
        enc = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("ascii").rstrip("=")
        next_cursor = enc

    # update last_seen
    client["last_seen_at"] = _iso(now)
    client["updated_at"] = _iso(now)
    _save("api_clients.json", api_clients)

    # log call
    latency_ms = int((time.time() - t0) * 1000)
    ev_id = "ue_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
    ts = now
    usage_events.append({
        "id": ev_id,
        "client_id": client_id,
        "event_type": "tool_run_completed",
        "investigation_id": investigation_id,
        "tool_run_id": None,
        "tool_name": "osint_overview",
        "occurred_at": _iso(ts),
        "meta": {"endpoint": "list_tool_runs", "status": "OK", "latency_ms": latency_ms, "returned": len(out), "total_matched": total},
        "created_at": _iso(ts),
        "updated_at": _iso(ts),
    })
    _save("usage_events.json", usage_events)

    return {"tool_runs": out, "pagination": {"limit": limit, "has_more": has_more, "next_cursor": next_cursor, "total": total}}

def get_tool_run(api_key, tool_run_id, include_artifacts=None, artifact_types=None, include_artifact_content=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0003000" if __import__("os").path.isdir("./environment_mix/0003000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(tool_run_id, str) or not tool_run_id.strip():
        return _err("VALIDATION_ERROR", "tool_run_id must be a non-empty string")
    if include_artifacts is None:
        include_artifacts = False
    if include_artifact_content is None:
        include_artifact_content = False
    if not isinstance(include_artifacts, bool):
        return _err("VALIDATION_ERROR", "include_artifacts must be a boolean")
    if not isinstance(include_artifact_content, bool):
        return _err("VALIDATION_ERROR", "include_artifact_content must be a boolean")

    allowed_artifacts = {"stdout", "stderr", "raw_json", "parsed_summary", "scan_results", "dns_records", "whois_record", "host_resolution", "dnstwist_permutations", "overview_report"}
    if artifact_types is not None:
        if not isinstance(artifact_types, list) or any((not isinstance(x, str) or x not in allowed_artifacts) for x in artifact_types):
            return _err("VALIDATION_ERROR", "artifact_types must be an array of valid artifact_type values", allowed=list(sorted(allowed_artifacts)))

    api_clients = _load("api_clients.json")
    tool_runs = _load("tool_runs.json")
    artifacts = _load("tool_run_artifacts.json")
    usage_events = _load("usage_events.json")

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    # auth
    client = None
    for c in api_clients:
        if isinstance(c, dict) and (c.get("id") == api_key or c.get("api_key_hash") == api_key):
            client = c
            break
    if client is None:
        derived = hashlib.sha256(api_key.encode("utf-8")).hexdigest()
        for c in api_clients:
            if isinstance(c, dict) and c.get("api_key_hash") == derived:
                client = c
                break
    if client is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    client_id = client.get("id")
    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "Client is not active")

    # rate limit
    rpm_limit = client.get("requests_per_minute_limit")
    if not isinstance(rpm_limit, int) or rpm_limit < 1:
        return _err("UNAUTHORIZED", "Client misconfigured (requests_per_minute_limit)")
    window_start = now - datetime.timedelta(minutes=1)
    cnt = 0
    for e in usage_events:
        if isinstance(e, dict) and e.get("client_id") == client_id:
            dt = _parse_dt(e.get("occurred_at"))
            if dt and dt >= window_start:
                cnt += 1
    if cnt >= rpm_limit:
        ev_id = "ue_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
        ts = now
        usage_events.append({
            "id": ev_id,
            "client_id": client_id,
            "event_type": "tool_run_failed",
            "investigation_id": None,
            "tool_run_id": None,
            "tool_name": "osint_overview",
            "occurred_at": _iso(ts),
            "meta": {"endpoint": "get_tool_run", "status": "RATE_LIMIT"},
            "created_at": _iso(ts),
            "updated_at": _iso(ts),
        })
        _save("usage_events.json", usage_events)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # find tool run
    tr = None
    for r in tool_runs:
        if isinstance(r, dict) and r.get("id") == tool_run_id:
            tr = r
            break
    if tr is None:
        ev_id = "ue_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
        ts = now
        usage_events.append({
            "id": ev_id,
            "client_id": client_id,
            "event_type": "tool_run_failed",
            "investigation_id": None,
            "tool_run_id": None,
            "tool_name": "osint_overview",
            "occurred_at": _iso(ts),
            "meta": {"endpoint": "get_tool_run", "status": "NOT_FOUND", "tool_run_id": tool_run_id},
            "created_at": _iso(ts),
            "updated_at": _iso(ts),
        })
        _save("usage_events.json", usage_events)
        return _err("NOT_FOUND", "Tool run not found")
    if tr.get("client_id") != client_id:
        ev_id = "ue_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
        ts = now
        usage_events.append({
            "id": ev_id,
            "client_id": client_id,
            "event_type": "tool_run_failed",
            "investigation_id": None,
            "tool_run_id": None,
            "tool_name": "osint_overview",
            "occurred_at": _iso(ts),
            "meta": {"endpoint": "get_tool_run", "status": "UNAUTHORIZED", "tool_run_id": tool_run_id},
            "created_at": _iso(ts),
            "updated_at": _iso(ts),
        })
        _save("usage_events.json", usage_events)
        return _err("UNAUTHORIZED", "Not permitted to access this tool run")

    tr_out = {
        "id": tr.get("id"),
        "investigation_id": tr.get("investigation_id"),
        "tool_name": tr.get("tool_name"),
        "status": tr.get("status"),
        "input_target": tr.get("input_target"),
        "input_domain": tr.get("input_domain"),
        "exit_code": tr.get("exit_code"),
        "error_message": tr.get("error_message"),
        "duration_ms": tr.get("duration_ms"),
        "started_at": tr.get("started_at"),
        "finished_at": tr.get("finished_at"),
        "created_at": tr.get("created_at"),
        "updated_at": tr.get("updated_at"),
    }

    out_artifacts = None
    if include_artifacts:
        wanted = set(artifact_types) if artifact_types is not None else None
        rows = []
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("tool_run_id") != tool_run_id:
                continue
            at = a.get("artifact_type")
            if wanted is not None and at not in wanted:
                continue
            row = {
                "id": a.get("id"),
                "artifact_type": at,
                "bytes": a.get("bytes"),
                "content_sha256": a.get("content_sha256"),
                "redacted": a.get("redacted"),
                "created_at": a.get("created_at"),
            }
            if include_artifact_content:
                row["content_text"] = a.get("content_text")
                row["content_json"] = a.get("content_json")
            rows.append(row)
        # stable order by created_at asc then artifact_type
        def _k(x):
            dt = _parse_dt(x.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, x.get("artifact_type") or "")
        rows.sort(key=_k)
        out_artifacts = rows

    # update last_seen
    client["last_seen_at"] = _iso(now)
    client["updated_at"] = _iso(now)
    _save("api_clients.json", api_clients)

    # log call
    latency_ms = int((time.time() - t0) * 1000)
    ev_id = "ue_" + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
    ts = now
    usage_events.append({
        "id": ev_id,
        "client_id": client_id,
        "event_type": "tool_run_completed",
        "investigation_id": tr.get("investigation_id"),
        "tool_run_id": tool_run_id,
        "tool_name": tr.get("tool_name"),
        "occurred_at": _iso(ts),
        "meta": {"endpoint": "get_tool_run", "status": "OK", "latency_ms": latency_ms, "include_artifacts": include_artifacts, "include_artifact_content": include_artifact_content},
        "created_at": _iso(ts),
        "updated_at": _iso(ts),
    })
    _save("usage_events.json", usage_events)

    resp = {"tool_run": tr_out}
    if include_artifacts:
        resp["artifacts"] = out_artifacts
    return resp

def get_current_client(api_key, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0003000" if __import__("os").path.isdir("./environment_mix/0003000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    now_iso = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        import uuid
        return f"{prefix}_{uuid.uuid4().hex}"

    def _append_usage(events, client_id, event_type, status=None):
        ts = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        meta = {"endpoint": "get_current_client"}
        if status:
            meta["status"] = status
        row = {
            "id": _gen_id("osint_ue"),
            "client_id": client_id,
            "event_type": event_type,
            "investigation_id": None,
            "tool_run_id": None,
            "tool_name": None,
            "occurred_at": ts.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "meta": meta,
            "created_at": ts.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
            "updated_at": ts.replace(microsecond=0).isoformat().replace("+00:00", "Z"),
        }
        events.append(row)
        return row

    def _auth_client_by_key(api_key_value, api_clients):
        for c in api_clients:
            if not isinstance(c, dict):
                continue
            if c.get("id") == api_key_value or c.get("api_key_hash") == api_key_value:
                return c
        return None

    def _rpm_count(events, client_id, since_dt):
        c = 0
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_id:
                continue
            odt = _parse_dt(e.get("occurred_at"))
            if odt and odt >= since_dt:
                c += 1
        return c

    def _count_type(events, client_id, event_type, since_dt):
        c = 0
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("client_id") != client_id or e.get("event_type") != event_type:
                continue
            odt = _parse_dt(e.get("occurred_at"))
            if odt and odt >= since_dt:
                c += 1
        return c

    # validate
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")

    api_clients = _load("api_clients.json")
    usage_events = _load("usage_events.json")

    client = _auth_client_by_key(api_key, api_clients)
    if client is None:
        return _err("UNAUTHORIZED", "Invalid API key")

    if client.get("status") != "active":
        return _err("UNAUTHORIZED", "API client is not active")

    client_id = client.get("id")
    minute_ago = now - datetime.timedelta(minutes=1)
    day_ago = now - datetime.timedelta(hours=24)
    rpm_used = _rpm_count(usage_events, client_id, minute_ago)
    inv_used = _count_type(usage_events, client_id, "investigation_created", day_ago)
    tool_used = _count_type(usage_events, client_id, "tool_run_created", day_ago)

    # log the request (best available usage event type)
    _append_usage(usage_events, client_id, "tool_run_completed", status="ok")
    client["last_seen_at"] = now_iso
    client["updated_at"] = now_iso
    _save("usage_events.json", usage_events)
    _save("api_clients.json", api_clients)

    safe_client = {k: v for k, v in client.items() if k != "api_key_hash"}
    return {
        "client": safe_client,
        "usage": {
            "requests_last_minute": rpm_used,
            "requests_per_minute_limit": client.get("requests_per_minute_limit"),
            "investigations_last_24h": inv_used,
            "daily_investigation_limit": client.get("daily_investigation_limit"),
            "tool_runs_last_24h": tool_used,
            "daily_tool_run_limit": client.get("daily_tool_run_limit"),
        },
        "meta": {"latency_ms": int((time.time() - t0) * 1000)},
    }
